quests[14102] = { id = 14102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelrufer Yngvar", description = "Die Kvaldir sind zur Küste von Nordend zurückgekehrt und wenn sich niemand um sie kümmert, werden sie verhindern, dass Vorräte und Verstärkung hier ankommen. Einer von ihnen, bekannt als Nebelrufer Yngvar, hat sich in einer Höhle auf der Westseite von Hrothgars Landestelle eingenistet. Von dort aus beeinflusst er den Nebel, um die Kvaldir und deren Meeresbestien zu verbergen.\n\nHier, nehmt diesen Glücksbringer und überquert die Meerenge nördlich des Turnierplatzes in Richtung Hrothgars Landestelle. Findet die Höhle des Nebelrufers und bringt ihn mithilfe des Glücksbringers zum Vorschein.", sourceObjective = "Hochmeister Adelard auf dem Argentumturnierplatz möchte, dass Ihr Nebelrufer Yngvar tötet.", completion = "Ihr habt uns kostbare Zeit verschafft, um gegen die Kvaldir vorzurücken und das Meer von diesen Quälgeistern zu befreien. Der Argentumkreuzzug steht einmal mehr in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[14103] = { id = 14103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanstaub", progress = "Hallo, {name}! Habt Ihr was zum Handeln?", completion = "Wunderbar! Noch eine Ladung Pulver!\n\nUnter uns Juwelenschleifern, ich habe bei den Magiern von Dalaran ein Riesengeschäft mit Schmuck aus \"reinem Titanium\" gemacht. Selbst mit ihrem überragenden Verstand sind sie nicht schlau genug, was Ihr Gold angeht. Ich bin hier, falls Ihr noch mehr bekommen solltet." }
quests[14104] = { id = 14104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ornolf der Vernarbte", description = "Ornolf der Vernarbte gilt als angsteinflößender Plünderer und ist unter seinen Kvaldirbrüdern bekannt dafür, Schiffe zu plündern und zu kapern. Vom Schiff Bors Zorn aus greifen seine Mannschaft und er unsere Schiffe an und stehlen unsere Ladung.\n\nOrnolf und seine Männer gehören zu denjenigen, die Mord an den Einwohnern einer Tuskarrinsel begangen haben und diese in Hrothgars Landestelle umbenannten. Sein Schiff liegt am östlichen Ende des Hafens der Insel vor Anker. Nehmt diesen erbeuteten Banner an Euch und stellt ihn auf diesem Schiff auf, um ihn zu provozieren und in den Kampf mit Euch zu locken.", sourceObjective = "Hochmeister Adelard auf dem Argentumturnierplatz möchte, dass Ihr Ornolf den Vernarbten tötet.", completion = "Ornolfs Mannschaft wird Ihren Anführer rächen wollen, aber ohne ihn werden sie einfacher zu besiegen sein. Wir haben unser Leben der Aufgabe geweiht, die Eiskrone von der Geißel und anderem Bösen zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[14105] = { id = 14105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todessprecher Kharos", description = "Der Kult der Verdammten hat seine Anstrengungen verdoppelt, um unsere Vernichtung herbeizuführen. Sie sind mutig geworden und sammeln in Todessprechers Wacht auf dem Gebirgskamm westlich des Turnierplatzes ihre Kräfte.\n\nDer erbarmungslose Todessprecher Kharos hat seinen Männern befohlen, ihre Stellungen zu befestigen, um sich darauf vorzubereiten, alle Waffen des Kults einzusetzen.\n\nMeine Männer bereiten sich und die Recken darauf vor, den Platz zu verteidigen - ich möchte jedoch, dass Champions wie Ihr, {name}, unsere Streitkräfte anführen, um den Angriff abzuschwächen. Findet Todessprecher Kharos und tötet ihn.", sourceObjective = "Hochmeister Adelard auf dem Argentumturnierplatz möchte, dass Ihr Todessprecher Kharos tötet.", completion = "Wahrhaftig, Ihr seid ein Beispiel für alle, die sich unter unserem Banner versammelt haben, {name}. Gemeinsam werden wir der Geißel zeigen, dass wir nicht in die Knie gezwungen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14106] = { id = 14106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Na Kada's Questtest" }
quests[14107] = { id = 14107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Gefallenen", description = "Der Argentumkreuzzug ist wohl kaum die erste Streitmacht, die den Lichkönig herausfordert. Unser Feind hetzt die Geister der Gefallenen gegen uns auf.\n\nSie streifen im Tal der Gefallenen Helden südwestlich des Platzes zwischen Aldur'thar und dem Eisenwallbollwerk umher. Die Gegend ist mit weggeworfenen Seelenkristallen, mit denen die Geißel die Geister kontrolliert, übersät. Sammelt diese Seelenkristalle und verwendet sie gemeinsam mit diesem lichtgesegneten Relikt, um den Geistern den Segen des Friedens zu verleihen. Sie haben ihre Ruhe mehr als verdient.", sourceObjective = "Kreuzfahrer Silberdämmerung möchte, dass Ihr dafür sorgt, dass 6 Geister der gefallenen Helden Frieden finden.", completion = "Ihr habt unseren gefallenen Brüdern einen großen Dienst erwiesen und es uns erspart, ihnen erneut auf dem Schlachtfeld begegnen zu müssen. Mit dem Voranschreiten der Kampagne gegen die Geißel ertappe ich mich dabei, über mein eigenes Schicksal nachzusinnen.\n\nSollte ich fallen, {name}, würde ich wollen, dass Ihr dasselbe für mich tätet wie an diesem heutigen Tage für die Geister der Gefallenen. Ich könnte den Gedanken nicht ertragen, meinen eigenen Bruder dazu zu zwingen, mich immer wieder zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14108] = { id = 14108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kraken am Haken", description = "Die Sonnenhäscher und der Silberbund haben Schiffe nach Norden entsandt, um die Kvaldir bei Hrothgars Landestelle anzugreifen, jedoch wurden sie von einem Seeräuberschiff der Kvaldir abgefangen und anschließend gefangen genommen. Was die Sache noch schlimmer macht, ist, dass die Kvaldir einen Weg gefunden haben, den gefürchteten Kraken aus den Tiefen des Nordmeeres hervorzurufen. Wenn irgendjemand an Bord da lebend herauskommen soll, muss der Kraken weggejagt und das Beschwörungsritual der Kvaldir... unterbrochen werden.\n\nHier <Kreuzfahrer/Kreuzfahrerin>, nehmt diese Speere. Ein Argentumhippogryph wird Euch in die Schlacht tragen.", sourceObjective = "Kreuzfahrer Silberdämmerung möchte, dass Ihr auf einen Argentumhippogryph steigt, 8 flammende Speere auf den Nordmeerkraken werft und 6 Tiefenrufer der Kvaldir ausschaltet.\n\nIhr findet die Argentumhippogryphen gleich außerhalb des Zelts auf dem Argentumturnierplatz.", progress = "Habt Ihr den Kraken schon verjagt? Beeilt Euch, Kreuzfahrer! Es bleibt nicht viel Zeit.", completion = "Kreuzfahrer, Ihr habt den Seemännern womöglich gerade genug Zeit verschafft, um ihre Flucht zu ermöglichen. Vielleicht werden die Leute vom Silberbund und die Sonnenhäscher das nächste Mal hinhören, bevor sie sich Hals über Kopf auf den Feind stürzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14109] = { id = 14109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganz neues Ihr", description = "Ein neues Outfit? Was Ihr nicht sagt! Eure Party ist in aller Munde. Alles, was auf der Insel Rang und Namen hat, wird da sein.\n\nNun, dann wünsche ich Euch viel Spaß beim Einkaufen. In der Gaunergasse könnt Ihr die besten Schnäppchen ergattern!", sourceObjective = "Kauft strahlende Klunker von Gappy Silberzahn, ein hippes neues Outfit von Szabo und eine coole Sonnenbrille von Missa Spekkies in der Gaunergasse.", progress = "Hast du alles beisammen, {name}? Ich kann es kaum erwarten, die neuen Sachen an dir zu sehen.\n\nDu hast doch keinen Ramsch gekauft, oder?", completion = "Oh, du wirst so toll aussehen! Allerdings nicht so toll wie ich. Bei deinem Tempo wirst du den Handelsprinzen im Handumdrehen vom Thron stoßen!\n\nIch kann es kaum abwarten, endlich nicht mehr arbeiten zu müssen! Du kaufst mir doch alles, was ich will, oder, Liebling?\n\nLass mich dir die ganzen Sachen abnehmen. Kurz bevor die Party losgeht werde ich dir beim Styling helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14110] = { id = 14110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganz neues Ihr", description = "Ein neues Outfit? Was Ihr nicht sagt! Eure Party ist in aller Munde. Alles, was auf der Insel Rang und Namen hat, wird da sein.\n\nNun, dann wünsche ich Euch viel Spaß beim Einkaufen. In der Gaunergasse könnt Ihr die besten Schnäppchen ergattern!", sourceObjective = "Kauft strahlende Klunker von Gappy Silberzahn, ein hippes neues Outfit von Szabo und eine coole Sonnenbrille von Missa Spekkies in der Gaunergasse.", progress = "Hast du alles beisammen, {name}? Ich kann es kaum erwarten, die neuen Sachen an dir zu sehen.\n\nMmm hmm!", completion = "Oh, du wirst so scharf aussehen! Bei deinem Tempo wirst du den Handelsprinzen im Handumdrehen vom Thron stoßen!\n\nIch kann es kaum abwarten, endlich ein gemachter Mann zu sein!\n\nLass mich dir die ganzen Sachen abnehmen. Kurz bevor die Party losgeht, werde ich dir beim Styling helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14111] = { id = 14111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikt des Irdenen Rings", description = "Ihr seid weit in Eurem Training vorangekommen, {name}. Nun, da Ihr die vier grundlegenden Elemente voll und ganz beherrscht, müsst Ihr Euch darum bemühen, alle vier im Gleichgewicht zu halten. Diese Disziplin hat einen praktischen Vorteil: Mit etwas Übung könnt Ihr nur ein einziges Relikt tragen anstatt alle vier Totems.\n\nSprecht mit Weitseher Eannu in der Nähe der Großen Schmiede in Eisenschmiede. Er wird Euch dabei helfen, Eure Beherrschung der Elemente zu verfeinern.", sourceObjective = "Bringt Eure vier Totems nach Eisenschmiede zu Weitseher Eannu.", progress = "In Euch regen sich die Geister. Was bringt Euch dazu, die Hilfe des Irdenen Rings zu suchen?", completion = "Wie ich sehe, beherrscht Ihr nun den Gebrauch der vier Totems. Ihr seid auf dem Weg, eins mit den elementaren Geistern zu werden - aber dies ist erst der Anfang Eurer Reise.\n\nHier, akzeptiert dies als Geschenk des Irdenen Rings. Tragt dieses Relikt bei Euch und die Macht aller vier Elemente wird Euch zu Diensten stehen.\n\nEuer Training muss weitergehen! Ich spüre, dass diese Welt sehr viele Prüfungen erwarten, und wir werden die Macht der Elemente hinter uns wissen müssen, wenn wir die Oberhand gewinnen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14112] = { id = 14112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was fressen eigentlich Yetis?", description = "Die Kreuzfahrer haben einen Yeti eingefangen, den sie Eisheuler nennen. Er soll an den Kämpfen im Kolosseum teilnehmen und man hat uns gebeten, bei Training und Unterhalt zu helfen.\n\nDie Kreuzfahrer waren nicht begeistert von meinem Vorschlag, der Bestie überschüssige Sonnenhäscher zum Fressen zu geben. Die Kreatur hat eine Vorliebe für Haifischfleisch, also will ich, dass Ihr zur Silberklinge hinunterfliegt, die in der Meerenge gen Norden schwimmt. Besorgt Euch ein wenig frischen Köder aus einem der Kübel auf dem Boot und schüttet ihn ins Wasser, um Haie damit anzulocken.", sourceObjective = "Savinia Lehrensang auf dem Argentumturnierplatz möchte, dass Ihr ihr 3 Stück Fleisch eines Nordmeerhais bringt.", progress = "Ich hoffe, dass Ihr etwas habt, mit dem ich Eisheuler füttern kann, sonst werde ich wirklich damit anfangen, Sonnenhäscher in seinen Käfig zu schmeißen.", completion = "Ich bin froh, dass wir das geschafft haben. Es ist zwar nicht die glanzvollste Aufgabe, aber als wir uns mit dem Argentumkreuzzug zusammengetan haben, versprachen wir, ohne Murren alles zu tun, was sie von uns verlangen. Natürlich kann man dasselbe nicht von den Sonnenhäschern behaupten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14113] = { id = 14113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mittelpunkt der Party", description = "Oh, meine Güte, Baby! Alle sind gekommen! Wen interessiert da schon irgendein blöder Drache?\n\nWir veranstalten die Party am Pool. Klingt so, als würden sich alle schon köstlich amüsieren. Du wirst so toll aussehen!\n\nWarum gehst Du nicht schon einmal rüber zum Pool und unterhältst die Leute? Ich bin in einer Minute bei Dir... Ich will nur kurz in etwas Aufregenderes schlüpfen.", sourceObjective = "Zieht Eure großartige Partyausstattung an (Coole Sonnenbrille, Hippes neues Outfit und Strahlende Klunker). Begebt Euch danach auf die Party am Pool des Hauptgeschäftssitzes der HGK und unterhaltet 10 kezanische Feiernde.", completion = "Sehr gut, mein Herr. Die Party war anscheinend ein voller Erfolg!\n\nÄh… was ist das denn?", sourceObjectiveStatus = "unverified-source-field" }
quests[14115] = { id = 14115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeladene Piraten", description = "Oh je! Piraten!\n\n{name}, da sind ungeladene Südmeerpiraten auf Eurer Party!\n\nIhr müsst sofort etwas dagegen unternehmen oder Eure Karriere und jede Hoffnung, <der nächste Handelsprinz/die nächste Handelsprinzessin> zu werden, sind dahin.", sourceObjective = "Tötet 12 ungeladene Piraten, um Eure Karriere zu retten.", completion = "Puh, das war knapp, Boss. Und leider habe ich noch mehr schlechte Nachrichten.\n\nBitte, erschießt mich nicht…", sourceObjectiveStatus = "unverified-source-field" }
quests[14116] = { id = 14116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ungeladene Gast", description = "Während Ihr Euch um die Piraten gekümmert habt, habe ich bemerkt, wie der Handelsprinz sich nach oben geschlichen hat. Er ist auf dem Balkon oben an der Treppe.\n\n{name}, ich glaube, er hat die Piraten geschickt.\n\n<Sassy erschaudert.>\n\nIhr solltet lieber so schnell wie möglich nach oben gehen. Lasst ihn nicht warten!", sourceObjective = "Sprecht mit Handelsprinz Gallywix oben im Hauptgebäude des Hauptgeschäftssitzes der HGK auf Kezan.", completion = "So, so, so, wenn das nicht mein abtrünniger Schützling Herr {name} ist.\n\nIch bin tief verletzt und enttäuscht. Ihr habt mich nicht zu Eurer kleinen Party da draußen eingeladen. Tut mir leid wegen der ungebetenen Gäste… Ihr wisst ja, wie Piraten sein können.\n\nAlso, kommen wir zum Geschäft?", sourceObjectiveStatus = "unverified-source-field" }
quests[14117] = { id = 14117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen von Eschental", description = "Unsere Feinde sind in der Überzahl, {class}, sogar direkt hier an unserer Türschwelle. Die Nachtelfen haben die Talrendisspitze verstärkt, weil sie unser Vordringen im Eschental unterbinden wollten. In diesem Augenblick patrouillieren ihre Späher in den nahegelegenen Hügeln und berichten über jedes Ein- und Ausgehen an diesen Toren.\n\nWir müssen Eschental diese Augen herausreißen.\n\nGeht. Eure Beute schleicht um diese Tore herum, insbesondere im Osten. Vernichtet die Späher, die uns beschatten!", sourceObjective = "Tötet 8 Späher der Talendrisspitze.", completion = "Ausgezeichnet. Wenn ihre Späher ihnen nicht länger berichten, wird die Talendrisspitze selbst die Furcht zu spüren bekommen, die sie uns einflößen wollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[14118] = { id = 14118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildbret für die Truppen", description = "Während wir die Ressourcen dieses Landes für unsere Kriegsmaschinerie aufbrauchen, berauben wir die einheimischen Tiere ihrer Heimat. Wenn sie ohnehin sterben müssen, sollte ihr Fleisch aber dennoch nicht verschwendet werden. Nicht wenn die Schlünde von Orgrimmar weit geöffnet und hungrig sind.\n\nTötet die geschwächten Mooshufhirsche, die sich noch in diesem Gebiet aufhalten und bringt ihr Fleisch unseren Peons und Grunzern mit.", sourceObjective = "Sammelt 15 Scheiben Wildbret von geschwächten Mooshufhirschen.", progress = "Ihr riecht nach frisch getötetem Wild, {class}.", completion = "Wild – und zwar reichlich! Gute Arbeit. Das wird unsere Mägen füllen, während wir unser Arsenal bauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14120] = { id = 14120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Bazillion Moneten?!", description = "Ihr seid ein sehr ehrgeiziger junger Goblin, {name}. Vielleicht ein wenig ehrgeiziger, als es für Euch gut wäre. Ich erkenne mich selbst in Euch, als ich noch jung war.\n\nIch habe einen Vorschlag. Vielleicht ist Euch ja schon aufgefallen, dass der Kajaro explodiert. Alle auf Kezan werden sterben!\n\nAber, wenn Ihr mir eine Bazillion Moneten bringt, bevor meine Yacht die Insel verlässt, werde ich dafür sorgen, dass Ihr unter den wenigen Glücklichen seid, die entkommen.\n\nWenn Ihr also leben wollt, solltet Ihr Euch lieber schnell überlegen, wo Ihr so viel Knete für mich auftreibt!", sourceObjective = "Sprecht mit Sassy Hartzang im Hauptgeschäftssitz der HGK auf Kezan.", completion = "Eine Bazillion Moneten?!? Wo sollen wir denn so viel Knete her bekommen?\n\n<Sassy überlegt einen Augenblick.>\n\nÄh… hat der Handelsprinz erwähnt, ob ich mit Euch zusammen auf seiner Yacht fliehen darf?", sourceObjectiveStatus = "unverified-source-field" }
quests[14121] = { id = 14121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plündert die Plünderer", description = "Wir werden alle sterben!!!\n\n<Ihr gebt Megs eine Ohrfeige, damit sie sich beruhigt.>\n\nTut mir leid, <Herr/Frau> {name}! Es wird nicht mehr vorkommen. Wir müssen einen Weg finden, ganz schnell ganz viel Knete zu scheffeln.\n\nEs gibt bereits Berichte, dass der Handelsprinz angeheuerte Plünderer auf die Straßen des Bilgepiers geschickt hat.\n\nNehmt den Hot Rod, fahrt sie über den Haufen und nehmt Euch die Beute, die sie sich unrechtmäßig angeeignet haben. Daran wäre doch nichts Falsches, oder?\n\nSchließlich ist es für eine gute Sache!", sourceObjective = "Benutzt den Hot Rod, um 12 angeheuerte Plünderer umzufahren, und sammelt dabei 12 Einheiten gestohlene Beute.", progress = "Konntet Ihr etwas von der gestohlenen Beute zurückstehlen?", completion = "Ihr habt es wirklich geschafft?! Na, ich schätze, das haben sie verdient.\n\nDas ist aber ganz schön viel Beute. Meint Ihr, es reicht, um Euch einen Platz auf der Yacht des Handelsprinzen zu erkaufen?\n\nKönnt Ihr jemanden mitnehmen? Ich habe im Marketing gerade nicht allzu viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[14122] = { id = 14122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Banküberfall", description = "All Eure Besitztümer wurden eingefroren und die Erste Bank von Kezan hat geschlossen!\n\nIhr braucht wirklich einen Haufen Knete, Boss. Ich fürchte, Ihr müsst Euer eigenes Geld aus der Bank rauben! Mit den verschiedenen Apparaten in Eurem goblinischen Alles-in-1-zigartigen Gürtel solltet Ihr alles dabei haben, was Ihr braucht, um den Tresor zu knacken.\n\nIch hoffe nur, dass Ihr etwas für schlechte Zeiten gespart habt, wie ich es Euch immer geraten habe. Und falls Ihr es noch nicht gemerkt haben solltet: Die Zeiten sind gerade hundsmiserabel!", sourceObjective = "Knackt den Tresor der Ersten Bank von Kezan, um an Eure privaten Reichtümer zu gelangen.", progress = "Habt Ihr sie? Habt Ihr den Tresor geknackt und Eure privaten Reichtümer aus der Bank geholt?", completion = "He, Ihr habt ja gespart! Ich bin so stolz auf Euch!\n\n<Sassy zählt all Eure Moneten.>\n\nÄh, Boss… Das reicht nicht einmal ansatzweise.", sourceObjectiveStatus = "unverified-source-field" }
quests[14123] = { id = 14123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfach hereinspaziert", description = "Ich habe von unseren Geldproblemen gehört. Es gibt nur einen Weg, wie wir eine Bazillion Moneten zusammenkriegen können: Wir stehlen es von den Reichen!\n\nDieser Schleimer, der Handelsprinz, hat alle möglichen Antiquitäten und wertvolle Kunstgegenstände gestohlen. Es ist an der Zeit, es ihm zu nehmen und den Bedürftigen zu geben... natürlich vor allem uns!\n\nHobart hat eine Kappe zurückgelassen, an der er gearbeitet hat - eine Verkleidung, mit der Ihr genauso ausseht, wie einer von Gallywix' Schergen. Ihr müsst einfach nur in seine Villa spazieren und diese Gegenstände \"sicherstellen\".\n\nPasst aber auf seine Schweine auf. Sie werden Euren Geruch hinter der Verkleidung erkennen!", sourceObjective = "Beschafft Euch Maltes Falken, die Mona Goblisa und die ultimative Bombe.", progress = "Habt Ihr die Waren, Boss?", completion = "Oh, toll! Dieser Kram ist ein Vermögen wert!\n\n<Slinky prüft alles mit geschulten, gierigen Augen.>\n\nIch hoffe nur, dass der Handelsprinz die Sachen nicht bemerkt, wenn Ihr sie ihm mit dem Rest Eures Reichtums übergebt…", sourceObjectiveStatus = "unverified-source-field" }
quests[14124] = { id = 14124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnappt Euch das Kaja'mit", description = "<Mein Herr/Meine Dame>, wir brauchen einen Haufen Knete, um den Handelsprinzen zu bezahlen und von Kezan weg zu kommen! Und dieser Haufen liegt genau da unten und wartet darauf, mitgenommen zu werden.\n\nDies sind die letzten bekannten Kaja'mitvorkommen. Das ist der Rohstoff, der uns zu den genialen Tüftlern und Alchemisten gemacht hat, die wir heute sind. Wenn das keine Bazillion Moneten wert ist, dann weiß ich auch nicht!\n\nNehmt ein paar meiner Kabummbomben und jagt die Vorkommen in die Luft. Sammelt danach die Kaja'mitbrocken auf.\n\nAber gebt auf die rebellischen Trolle Acht!", sourceObjective = "Sammelt 12 Kaja'mitbrocken.", progress = "Wie viel Kaja'mit habt Ihr?", completion = "Gute Arbeit, mein Herr, wirklich gute Arbeit! Da habt Ihr ein echtes Vermögen in Euren Taschen.\n\nDamit lässt uns der Handelsprinz sicher auf seine Yacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[14125] = { id = 14125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versicherungsbetrug", description = "Wir kommen der Sache näher, aber wir haben immer noch nicht genug Moneten. Zu Eurem Glück, Boss, habe ich das vorausgesehen und einen Plan entwickelt. Wir werden die Versicherung des Hauptquartiers einstreichen!\n\nIch habe mir die Freiheit genommen, das übriggebliebene Feuerwerk von Eurer Party an diesem Ort zu verteilen. Alles, was Ihr tun müsst, ist dorthin zu gehen und ein wenig Sabotage zu betreiben.\n\nDarf ich vielleicht den defekten Generator, den undichten Ofen und das leicht entzündliche Bett vorschlagen? Danach geht Ihr wieder nach draußen und schickt einen Gasbot hinein.\n\nEin narrensicherer Plan!", sourceObjective = "Überlastet den defekten Generator, macht den undichten Ofen an und lasst eine Zigarre auf das leicht entzündliche Bett fallen. Benutzt dann den Gasbot, um den Hauptgeschäftssitz der HGK in Brand zu setzen!", completion = "Das ist noch gar nichts. Ihr solltet den Bilgepier mal sehen… Dort steht alles in Flammen!\n\nGut, gut, ich habe keine Zeit, den Ort unter die Lupe zu nehmen. Hier ist die Knete aus der Versicherung des Bilgewasserkartells.\n\nIch muss einen Weg von der Insel herunter finden. Viel Glück, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[14126] = { id = 14126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebensersparnisse", description = "Wir haben die ganze Knete zusammen. Jetzt müssen wir nur noch eines tun, Boss: Euch zur Yacht des Handelsprinzen schaffen. Sie legt bald ab!\n\nWir müssen uns beeilen. Springt rein! Ich fahre!", sourceObjective = "Übergebt Handelsprinz Gallywix auf Gallywix' Yacht auf Kezan Eure Lebensersparnisse.", progress = "Oh, {name}, Ihr seid es. Welch unerwartete Überraschung.", completion = "Glückwunsch, Ihr habt es gerade noch geschafft. Wie ich sehe, habt Ihr mir alles gebracht, worum ich Euch gebeten habe, sogar den Hot Rod.\n\n<Ein bösartiges Grinsen huscht über das Gesicht des Handelsprinzen.>\n\nEine Bazillion Moneten war sicher nicht leicht zu beschaffen. Jetzt bin ich der reichste und mächtigste {race} in ganz Azeroth.\n\nZU DUMM, DASS ICH DIE BEDINGUNGEN UNSERER VEREINBARUNG JETZT ÄNDERE!\n\nIhr seid ab sofort mein Sklave. Geht unter Deck und leistet Euren Beitrag beim Kohleschaufeln. Nächster Halt: Azshara!\n\nMuhahahahahahaha!", sourceObjectiveStatus = "unverified-source-field" }
quests[14127] = { id = 14127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr der Hochgeborenen?", description = "Das Wachssiegel auf diesen Befehlen wurde erst vom Kurzen aufgebrochen. Ihr könnt die sorgfältig ausgeführte Elfenschrift nicht lesen, aber eine kleine handgemalte Karte deutet auf die nahegelegenen Ruinen. Unter der Karte stehen in einer gänzlich anderen Schrift eine Reihe von Runen in einer metallisch schimmernden Tinte.\n\nAg'tor wird diese wichtige Geheiminformation zweifelsohne sehen wollen.", sourceObjective = "Bringt die Befehle des Spähers zu Ag'tor Blutfaust am Hinteren Tor von Orgrimmar.", progress = "Ihr habt bei einer der Leichen etwas gefunden, sagt Ihr? Gebt es mir!", completion = "<Ag'tor hält das Pergament gegen das Licht und begutachtet es.>\n\nNein, ich kann dies ebenfalls nicht entziffern, aber was ich sehe, gefällt mir nicht. Sind das arkane Runen?\n\nIhr müsst dies einem Experten vorlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14128] = { id = 14128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr der Hochgeborenen?", description = "Unsere verbündeten Blutelfen haben die Runen auf dieser Karte untersucht und sie können die rätselhafte Schrift vermutlich entziffern. Sucht nach Malynea Himmelshäscher. Sie leitet ihre Untersuchungen vom Umschlagplatz der Raketenbahn von Orgrimmar nördlich von hier. Es ist ein Teil des neuen Transitsystems der Goblins, die sich durch dieses Land ziehen. Rasch, jetzt!", sourceObjective = "Bringt die Befehle des Spähers zu Malynea Himmelshäscher am Umschlagplatz der Raketenbahn von Orgrimmar.", progress = "Ich nehme an, bei dieser Unterbrechung handelt es sich um etwas Wichtiges?", completion = "Was? Her damit, sofort! Ag'tor hat Recht. Das sind arkane Runen. Sie erkunden magische Stätten? Experimentieren mit arkanen Künsten? Das ist ein erstaunlicher Bruch mit Jahrtausende alten Traditionen der Nachtelfen.\n\nHmph! Die Vorstellung, dass sie in diesem Bereich irgendwelche Fähigkeiten erlangen, ist absurd. Sogar für diejenigen, die sich selbst einst zu den Hochgeborenen zählten.\n\n<Malynea wirft die Schriftrolle verächtlich beiseite, aber auf ihrer Stirn bilden sich Sorgenfalten.>", sourceObjectiveStatus = "unverified-source-field" }
quests[14129] = { id = 14129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schredder außer Rand und Band", description = "Ich habe versucht, unsere neuen Verbündeten der Horde mit der legendären Effizienz der Goblins zu beindrucken, aber im Nachhinein war die Automatisierung der Schredder eine schlechte Idee. Jetzt sind es Tötungsmaschinen, die wahllos durch unsere Ländereien pflügen. Versteht mich nicht falsch, diese Geräte haben ihren Sinn und Zweck, aber jetzt käme <ein mutiger/eine mutige:c> {class} gerade recht, <der/die:c> mir hilft, diese Dinger unter Kontrolle zu bekommen.\n\nEs ist ganz einfach. Automatisierte Schredder müssen, wie alle Maschinen, geprügelt werden, bis sie sich unterwerfen. Danach übernehmt Ihr die Steuerung und ich funke Euch weitere Anweisungen zu.", sourceObjective = "Greift einen der entlaufenen Schredder in der Nähe der Tore von Orgrimmar an. Dann setzt Euch hinein, nachdem Ihr ihm erheblichen Schaden zugefügt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14130] = { id = 14130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freundschaft kennt keine Farbe", description = "Mein Bruder und ich werden gejagt.\n\nUnser Vatertier wurde kürzlich getötet und der schwarze Drachenschwarm hetzt diejenigen von uns, die noch am Leben sind. Ich bin hier, weil ich Azuregos finden und in Sicherheit bringen will, aber er macht es mir nicht leicht.\n\nAzuregos hat nicht viele Freunde und sein diesbezüglicher Geschmack ist ein wenig... ungewöhnlich. Der einzige, den ich hier in der Gegend kenne ist ein Murloc mit Namen Ergll. Ihr solltet ihn an der Küste nordöstlich von hier finden.\n\nTut, was immer vonnöten ist, um Azuregos zu finden und schickt ihn zu mir.\n\nBitte beeilt Euch.", sourceObjective = "Findet Ergll an der Küste der Ruinen von Arkkoran.", completion = "Heda! Ein neuer Freund! Bin sehr erfreut, Euch kennenzulernen. Mein Name ist Ergll. Das 'g' wird nicht gesprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14131] = { id = 14131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bohnensammler", description = "Azuregos... Azuregos... Azi? Der Großdrache? Wir sind Freunde, zweifellos! Er brachte mir das Sprechen bei. Er sagte, er mag meinen Farbton... ein Freund von Farben, oder?\n\nKann mich nicht erinnern, wo er hingegangen ist. Hmm... Vielleicht habt Ihr etwas, das meinem Gedächtnis auf die Sprünge hilft?\n\nIch ziehe hier am Strand Kahpheepflanzen. Sie mögen Sand. Ziemlich verrückt.\n\nKönntet Ihr mir ein paar ernten?", sourceObjective = "Pflückt 10 Kahpheebohnen von den Pflanzen in den Ruinen von Arkkoran.", progress = "Bin müde, so schwer sich zu konzentrieren.", completion = "Schöne Bohnen! Sie riechen absolut köstlich, oder etwa nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[14132] = { id = 14132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was für eine Frechheit!", description = "Ich würde sie mit ihnen teilen, wenn sie fragen würden. Sie fallen einfach über meine Kahpheepflanzen her. Das ist nicht nett! Ihr könntet ihnen eine Lektion erteilen.\n\nDiese blöden Makrinnis.", sourceObjective = "Tötet 10 Makrinnis in den Ruinen von Arkkoran.", completion = "Zu gemein? Nein, nicht zu gemein. Sie haben es verdient.\n\nIch zerstöre ihre Pflanzen doch auch nicht. Hab ich noch nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[14134] = { id = 14134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holz vor der Hütte", description = "Jetzt, wo Ihr das Ding unter Kontrolle habt, sammeln wir das Holz ein, das ich mitbringen sollte. Sonst bauen diese Orcs das nächste Katapult aus MIR!\n\nFrisches Holz sollte bereits aufgestapelt in der Gegend sein. Verwendet den Schredder und sammelt so viel auf, wie Ihr könnt.", sourceObjective = "Verwendet den umprogrammierten Schredder, um 6 Haufen azsharisches Holz zu sammeln. Falls Ihr Euren Schredder verliert, kann ein weiterer angegriffen und umprogrammiert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14135] = { id = 14135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Baum", description = "Haltet kurz still, ich mache die Steuerung für die Hauptmotorsäge betriebsbereit.\n\nScharfschützen der Nachtelfen von der Talrendisspitze verstecken sich in den Bäumen und greifen meine Arbeiter an. Ich will, dass Ihr diese Scharfschützen erledigt... indem Ihr Euch zunächst um diese Bäume kümmert. Sucht nach azsharischen Schösslingen östlich des Haupttores. Euer Schredder wird wissen, was zu tun ist. Schreddert los!", sourceObjective = "Verwendet die Motorsäge des Schredders, um die azsharischen Schösslinge niederzumähen und tötet 9 Scharfschützen von der Talrendisspitze, sobald sie auftauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14136] = { id = 14136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettungseinsatz auf See", description = "Die Kvaldir haben auf Hrothgars Landestelle, der kleinen Insel im Norden, ihr Lager aufgeschlagen. Wir haben Kapitän Aerthas Feuerfalke in die Gegend geschickt, aber er und seine Mannschaft sind auf eine Seeräuberbande der Kvaldir gestoßen, die in Richtung Turnierplatz unterwegs war! Nun wird die Feuerfalke von den Seeräubern angegriffen und ihre Mannschaft ist weit in der Unterzahl. Geht dort hinaus und zeigt diesen Kvaldir, weshalb es keine gute Idee ist, die Sonnenhäscher anzugreifen.\n\nDie Feuerfalke befindet sich zwischen Hrothgars Landestelle im Norden und dem Turnierplatz, auf der westlichen Seite der Straße der Meerhäscher.", sourceObjective = "Girana die Blutgezeichnete auf dem Argentumturnierplatz möchte, dass Ihr 8 Berserker der Kvaldir und 3 Harpunierer der Kvaldir an Bord der Feuerfalke tötet.", completion = "Gute Arbeit, Champion. Der Kampf geht weiter, aber nun wissen die Kvaldir, dass wir solche Angriffe nicht dulden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14138] = { id = 14138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst ist Dienst und Cola ist Cola", description = "Wir haben so viele Probleme unten in der Kaja'mine, dass Vorarbeiter Feuchtlunte bald schon Purzelbäume schlägt, so verzweifelt wie er nach Euch sucht. Er murmelte etwas von 'widerspenstigen Trollen'.\n\nDas Kaja'mit, das unsere Trolle abbauen, ist ein wesentlicher Bestandteil unserer Kaja'Cola. Dieses blubberige Zeug bringt uns ein Vermögen und Euch sicher die Beförderung <zum Handelsprinzen/zur Handelsprinzessin> ein!\n\nAber zunächst muss die Produktion wieder ins Rollen kommen. Ihr findet den Vorarbeiter im Osten. Hier, gebt ihm das als Motivation, damit er sich wieder zusammenreißt.", sourceObjective = "Bringt Sassys Motivation zu Vorarbeiter Feuchtlunte im Hauptgeschäftssitz der HGK auf Kezan.", progress = "Äh… alles läuft super. Ja.\n\nWas ist das?", completion = "Ein Geschenk von Sassy? Ich hoffe, es ist ein Bonus!", sourceObjectiveStatus = "unverified-source-field" }
quests[14140] = { id = 14140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einhalt den Aggressoren", description = "Die Kvaldir, räuberische Vrykul, die überall Angst und Schrecken verbreiten, haben unsere Lieferungen abgefangen und sämtliche Tuskarrbewohner einer Insel im Norden ermordet. Sie haben die Insel bereits in Hrothgars Landestelle umbenannt. Wenn es ihnen gelingt, dort langfristig Fuß zu fassen, werden wir mit Sicherheit zu ihrem nächsten Ziel.\n\nDie Streitkräfte des Kreuzzugs haben jedoch alle Hände voll zu tun mit der Geißel, und wir müssen den Turnierplatz beschützen. Fliegt vom Platz aus Richtung Norden, bis Ihr die Insel erreicht und nehmt Euch der Kvaldir an, bevor sie noch mehr zerstören können!", sourceObjective = "Girana die Blutgezeichnete auf dem Argentumturnierplatz möchte, dass Ihr 10 Kvaldir tötet.", completion = "Eure Taten haben bewiesen, dass wir Sonnenhäscher dem Argentumkreuzzug um einiges bessere Verbündete sind als der Silberbund, und dass wir es sein werden, die am Ende triumphieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[14141] = { id = 14141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormok will seine Schneebolde", description = "Zwei meiner Männer kamen schon bei dem Versuch um, den Magnatauren namens Gormok den Pfähler einzusperren, doch die Kreatur treibt noch immer ihr Unwesen. Sie heult und jammert stundenlang darüber, dass ihr Lieblingsschneebold nicht da ist.\n\nIch würde sie mit eigenen Händen töten, wenn der Argentumkreuzzug dieses Monster nicht ins Kolosseum schicken wollte. Vielleicht ist es an der Zeit, der Bestie ihr Spielzeug zu bringen. Hier, nehmt dieses Netz und begebt Euch nach Garms Bann im Südosten der Sturmgipfel gleich nordöstlich von K3. Fangt ein paar dieser Schneebolde und betet zum Licht, dass Ihr den richtigen gefunden habt.", sourceObjective = "Fangt mithilfe des beschwerten Netzes 8 schneeblinde Anhänger und bringt sie zu Tylos Dämmerflucht auf dem Argentumturnierplatz.", completion = "Je eher diese stinkenden Dinger aus meinen Augen verschwinden und in ihren Käfigen landen, um so schneller wird sich meine Stimmung bessern. Ich wünschte, der Argentumkreuzzug hätte dem Silberbund die Aufsicht über diese Kreatur gegeben. Die werden sich die Hände schmutzig machen müssen, wenn die Schlacht um die Zitadelle beginnt, und ich habe das Gefühl, dass sie sich als schwache und zimperliche Verbündete erweisen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14142] = { id = 14142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diesmal habt Ihr Euch wirklich selbst übertroffen, Kul", description = "Kreuzfahrer Kul hat sich mal wieder in Schwierigkeiten gebracht, nur dieses Mal hat er noch andere mit hineingezogen. Als er sah, wie Kultisten in Todessprechers Wacht westlich des Turnierplatzes ihr Lager aufschlugen, rief er die Streiter für einen Angriff zusammen.\n\nSie wurden mit Leichtigkeit gefangen genommen und nun schmachtet Kul in einem Käfig auf der Plattform im Lager. Ich bin mir sicher, dass der Kult die Gefangenen opfern wird - es sei denn, wir können sie retten. Jeder von diesen Kultisten könnte Schlüssel für die schwarzen Käfige bei sich haben. Findet die Schlüssel und befreit Kul und die gefangenen Streiter.", sourceObjective = "Rettet Kul den Tollkühnen und 4 gefangene Streiter aus Todessprechers Wacht und kehrt dann zu Girana der Blutgezeichneten auf dem Argentumturnierplatz zurück.", completion = "Kul wird weiterleben und sich wieder lächerlich machen. Und es ist keinesfalls das erste Mal, dass jemand Kul vor sich selbst retten musste. Es sind solche Beispiele, bei denen es einen nicht wundert, dass die meisten Streiter die Gewohnheiten des Silberbunds annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14143] = { id = 14143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legt mal ein Bein zu", description = "Der Argentumkreuzzug hatte ein schnelles Schiff mit einer Ladung Weitschreiterfleisch und weiteren Vorräten entsendet, die für uns hier am Turnierplatz vorgesehen waren, doch nie eingetroffen sind. Späher berichteten uns von einem Angriff der Kvaldir, räuberische Vrykul, die Angst und Schrecken auf den Meeren verbreiten.\n\nSie haben die Crew erschlagen und die Ladung auf eine Insel namens Hrothgars Landestelle gebracht. Wenn Ihr Richtung Norden blickt, könnt Ihr sie schemenhaft erkennen, verborgen im Nebel. Würdet Ihr uns helfen, das Diebesgut zurückzubeschaffen? Ohne diese Weitschreiterbeine werden wir bald hungern müssen.", sourceObjective = "Beschafft 10 gestohlene Weitschreiterbeine zurück und bringt sie zu Girana der Blutgezeichneten auf dem Argentumturnierplatz.", progress = "Konntet Ihr die gestohlenen Vorräte wiederbeschaffen?", completion = "Sie sehen etwas mitgenommen aus, doch sie sind noch immer genießbar. Die Kreuzzügler werden es gerne hören, dass wir ein wenig Erfolg hatten. Vielleicht können wir die leicht vergammelten Stücke dem Silberbund geben. Das würde mir den Tag versüßen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14144] = { id = 14144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Barmherzigkeit des Lichts", description = "Ich habe Beichtpatin Blondlocke aufmerksam gelauscht, und ich sage Euch, ihre Worte gaben mir zu denken. Zwar kämpfen wir Seite an Seite mit den Kreuzfahrern, aber wir könnten auch von ihnen lernen.\n\nAn der Nordküste liegt Hrothgars Landestelle, wo die seefahrenden Kvaldir eine alte Tuskarrsiedlung überrannt und deren Bewohner getötet haben. Nehmt dieses Buch und lest den Leichen der Dorfbewohner ihre Sterbesakramente. So ermöglicht Ihr ihren Seelen, die Fesseln der Nebel um die Insel abzustreifen und ihren Frieden zu finden.", sourceObjective = "Benutzt das Gebetsbuch der Beichtpatin, um 8 erschlagenen Tualiq-Bewohnern ihre Sterbesakramente zu lesen, und kehrt dann zu Girana der Blutgezeichneten auf dem Argentumturnierplatz zurück.", progress = "Habt Ihr Euch der Seelen der erschlagenen Tualiq-Bewohner angenommen?", completion = "<Girana nimmt das Gebetbuch von Euch entgegen.>\n\nIch danke Euch. Wir sind vielleicht nicht immer einer Meinung mit den Kreuzfahrern, aber ich habe in meiner Zeit hier viel von Beichtpatin Blondlocke gelernt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14145] = { id = 14145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was fressen eigentlich Yetis?", description = "Die Kreuzfahrer haben einen Yeti eingefangen, den sie Eisheuler nennen. Er soll an den Kämpfen im Kolosseum teilnehmen und man hat uns gebeten, bei Training und Unterhalt zu helfen.\n\nDie Kreuzfahrer waren nicht begeistert von meinem Vorschlag, ein paar Mitglieder des Silberbunds an die Bestie zu verfüttern. Die Kreatur hat eine Vorliebe für Haifischfleisch, also will ich, dass Ihr zum Schiff \"Scharlachroter Morgen\" hinunterfliegt, das in der Meerenge gen Norden schwimmt. Besorgt Euch ein wenig frischen Köder aus einem der Kübel auf dem Boot und schüttet ihn ins Wasser, um Haie damit anzulocken.", sourceObjective = "Tylos Dämmerflucht auf dem Argentumturnierplatz möchte, dass Ihr ihm 3 Stück Fleisch eines Nordmeerhais bringt.", progress = "Ich hoffe, dass Ihr etwas habt, mit dem ich Eisheuler füttern kann, sonst werde ich wirklich damit anfangen, Mitglieder des Silberbunds in seinen Käfig zu schmeißen.", completion = "Ich bin froh, dass wir das geschafft haben. Es ist zwar nicht die glanzvollste Aufgabe, aber als wir uns mit dem Argentumkreuzzug zusammengetan haben, versprachen wir, ohne Murren alles zu tun, was sie von uns verlangen. Natürlich kann man dasselbe nicht vom Silberbund behaupten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14146] = { id = 14146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt die Tore!", description = "Egah – was ist hier los?\n\n<Schreie, Rufe und Schlachtgetöse dröhnen über Funk.>\n\n{name}! Kommt sofort hierher zurück. Eilt zurück zu den Toren. Wir werden angegriffen!\n\nHelft uns, die Eindringlinge abzuwehren. Ich lade Euren Granatenwerfer!!", sourceObjective = "Arbeitsaufseher Grabbit will, dass Ihr zurück zum Hinteren Tor von Orgrimmar eilt und dort 20 Räuber der Nachtelfen tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14151] = { id = 14151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kardinalsrubin", description = "Man sagt, dass der Kardinalsrubin der feinste Edelstein in ganz Nordend ist. Er funkelt wie eine Kristallrose in der Sonne.\n\nBevor ich Euch die Herstellung beibringe, bitte ich Euch, fünf Transmutationen epischer Edelsteine durchzuführen, um auf diese Weise Euren Geist vorzubereiten. Welche Transmutationen Ihr wählt, das liegt bei Euch. Ihr könnt auch mehrmals dieselbe durchführen.\n\nKehrt zu mir zurück, wenn Ihr wirklich bereit seid.", sourceObjective = "Linzy Schwarzbolz in Dalaran möchte, dass Ihr 5 erfolgreiche Transmutationen epischer Edelsteine mithilfe Eurer Alchemiefertigkeit durchführt. Für die Transmutation akzeptable Edelsteine sind Ametrine, Augen von Zul, Schreckenssteine, Königsbernsteine und Fürstenzirkone.", completion = "Sehr gut, {name}.\n\nDer Trick bei der Sache ist nun, die Ausrichtung der Facetten gerade richtig hinzubekommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[14152] = { id = 14152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettungseinsatz auf See", description = "Champion, Kapitänin Schaumkrone und ihr Schiff wurden nach Norden entsandt, um die Kvaldir bei Hrothgars Landestelle zu behelligen, als sie von einer Seeräuberbande der Kvaldir abgefangen wurden, die in Richtung Turnierplatz unterwegs war! Unglücklicherweise sind die Kvaldir der Mannschaft an Bord zahlenmäßig um einiges überlegen und gerade dabei, das Schiff zu übernehmen.\n\nIhr müsst Euch auf nach Norden zur Schaumkrone machen, die sich in der Straße der Meerhäscher zwischen dem Turnierplatz und Hrothgars Landestelle befindet, und der Mannschaft helfen, den Angriff abzuwehren. Das Schiff sollte sich auf der Ostseite der Meeresenge befinden.", sourceObjective = "Begebt Euch in Richtung des Nordmeers und tötet unter den Angreifern der Schaumkrone 8 Berserker der Vrykul und 3 Harpunierer der Vrykul.", completion = "Es scheint, als wären die Dinge schlimmer, wie anfangs gedacht. Ihr habt noch immer Tapferkeit gezeigt und dabei viele Besatzungsmitglieder der Schaumkrone gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14153] = { id = 14153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mittelpunkt der Party", description = "Oh, wow, Baby! Alle sind gekommen! Wen interessiert da schon so ein blöder Drache?\n\nWir veranstalten die Party am Pool. Klingt so, als würden sich alle schon köstlich amüsieren. Ihr werdet so toll aussehen!\n\nWarum geht Ihr nicht schon einmal rüber zum Pool und unterhaltet die Leute? Ich bin in einer Minute bei Euch... Ich muss nur noch meine Sachen holen.", sourceObjective = "Zieht Eure großartige Partyausstattung an (Coole Sonnenbrille, Hippes neues Outfit und Strahlende Klunker). Begebt Euch danach auf die Party am Pool des Hauptgeschäftssitzes der HGK und unterhaltet 10 kezanische Feiernde.", completion = "Sehr gut, meine Dame. Die Party war anscheinend ein voller Erfolg!\n\nÄh… was ist das denn?", sourceObjectiveStatus = "unverified-source-field" }
quests[14154] = { id = 14154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit knapper Not", description = "Eine dieser räudigen Flohschleudern hat Dempsey ordentlich erwischt. Wir können ihn nicht fortbringen, bevor seine Blutungen nicht gestoppt sind.\n\nMacht Euch nützlich und haltet diese Bastarde zurück. Ein paar Minuten reichen uns schon, <Bruder/Schwester>!", sourceObjective = "Haltet die Worgen im oberen Bereich des Stadtgefängnisses von Gilneas 2 Minuten lang auf.", progress = "Wir haben's gleich! Vorsichtig, oder wir verlieren ihn!", completion = "Wir haben's geschafft, {name}. Dank Euch hat ein guter Mann überlebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14155] = { id = 14155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arborzid", description = "Wie steht es um den Schredder? Ich glaube, ich kann Eure Notfallenergievorräte einsatzbereit machen. Das wird Euch wiederaufladen, wenn Ihr beschädigt seid.\n\nHört gut zu. Diese Nachtelfen werden von einem Urtum des Krieges unterstützt, das sich westlich des Tores verwurzelt hat. Es ist ein gigantischer Baumriese. Ihr wisst, was zu tun ist! Legt ihn um!\n\nDafür seid Ihr wie geschaffen!!", sourceObjective = "Verwendet den Schredder, um das Urtum von der Talrendisspitze zu vernichten. Notfallersatzschredder stehen am Hinteren Tor von Orgrimmar zur Verfügung, wenn Ihr Euren verliert.", completion = "Ihr habt es geschafft, {name}! Die Eindringlinge haben sich zurückgezogen. Sie haben mir gesagt, ich sei verrückt, dass ich einen Granatenwerfer auf einem Schredder montiere...\n\nIhr habt mit dem Gerät gute Arbeit geleistet. Mit einer derartig beeindruckenden Darbietung direkt vor der Haustür des Kriegshäuptlings wird die Horde nicht mehr an den Möglichkeiten der Goblintechnologie zweifeln. Ich bin Euch zu großem Dank verpflichtet!", sourceObjectiveStatus = "unverified-source-field" }
quests[14157] = { id = 14157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Differenzen", description = "Lord Darius Crowley ist schon viele Dinge genannt worden. Rebell. Verräter. Terrorist.\n\nVor dem Bürgerkrieg nannte ich ihn einen ... Freund.\n\nIch habe ihn nie dafür verurteilt, einen Aufstand gegen mich angeführt zu haben. Sein Land und seine Bevölkerung waren durch eine zehn Meter hohe Mauer von Gilneas abgeschnitten ... Aber wir hatten keine Wahl.\n\nWie auch immer ... Crowley ist genau die Person, die wir jetzt brauchen.\n\nBetretet das Steinwallgefängnis und fragt Hauptmann Broderick, wo Crowley zu finden ist. Ich würde ja meine eigenen Männer schicken, aber es existiert immer noch böses Blut zwischen uns.", sourceObjective = "Sprecht mit Hauptmann Broderick im Steinwallgefängnis in Gilneas.", completion = "Graumähne will Crowley retten? Hat er den Verstand verloren?", sourceObjectiveStatus = "unverified-source-field" }
quests[14159] = { id = 14159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Arsenal des Rebellenlords", description = "Das Arsenal, von dem Crowley spricht, befindet sich in einem Keller westlich von hier.\n\nEs gefällt mir zwar nicht, dass meine Gegner Artillerie in die Stadt geschmuggelt haben, aber sie könnte dabei helfen, gilnearische Leben zu retten.\n\nFindet Josiah Avery und requiriert die Rebellenartillerie. Wir müssen diese Waffen sinnvoll einsetzen.", sourceObjective = "Sprecht mit Josiah Avery im Militärdistrikt in Gilneas.", completion = "Seht mich nicht an! Lasst mich in Ruhe!", sourceObjectiveStatus = "unverified-source-field" }
quests[14160] = { id = 14160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leistungsurkunde", description = "Auf diesem feinen Pergament befindet sich eine Liste mit einer großen Anzahl an Leistungen, die {name} in der Tradition des Juwelenschleifens errungen hat.\n\nBringt diese Urkunde zu Jonas Timotheus nach Dalaran zurück, um eine angemessene Belohnung zu erhalten.", sourceObjective = "Liefert die Leistungsurkunde bei Jonas Timotheus in Dalaran ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[14161] = { id = 14161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basilisken klatschen", description = "Wir haben diesen ganzen Berg abgetragen, um die Mineralien aus der Mine darunter abzubauen. Aber wir haben nicht bedacht, dass die Basilisken, die dort unterirdisch hausten nun, also, oberirdisch hausen. Ihr seht so unternehmungslustig aus. Geht dorthin und tötet ein paar dieser Plagegeister und ich greife für Euch einmal tief in unsere Geldvorräte.", sourceObjective = "Tötet 10 Grausteinbasilisken im Tagebau am Gebirgsfuß.", completion = "Gut, gut. Eine Sorge weniger.", sourceObjectiveStatus = "unverified-source-field" }
quests[14162] = { id = 14162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Horzak", description = "Ihr habt wirklich gute Arbeit geleistet, als Ihr unsere Holzfällerei zum Laufen gebracht habt. Aber ich habe gehört, dass wir langsam zu wenig Stein haben. Man sollte meinen, wenn wir Berge versetzen können, könnten wir dabei auch ein paar Steine aufsammeln...\n\nNun, das ist nicht mein Problem, aber vielleicht könnt Ihr es zu Eurem machen. Meldet Euch bei Horzak Zignibbel oben am Umschlagplatz der Raketenbahn von Orgrimmar. Findet heraus, ob Ihr ihm dabei helfen könnt, diese Operation in den Griff zu bekommen. Folgt der Straße Richtung Nordosten und Ihr findet ihn im Turm der Raketenbahn.", sourceObjective = "Findet Horzak Zignibbel am Umschlagplatz der Raketenbahn von Orgrimmar in Azshara.", completion = "Seid Ihr hier, um zu helfen? Ausgezeichnet! Hier, unterzeichnet diesen Abfindungsverzicht. Und hier die Wettbewerbsklausel. Fangen wir an!", sourceObjectiveStatus = "unverified-source-field" }
quests[14163] = { id = 14163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen: Insel der Eroberung", description = "Da wir dem Sieg in Eiskrone immer näher kommen, ist es deutlicher geworden, dass sich unsere Armeen mit der Horde auseinandersetzen müssen, bevor sie sich um den Lichkönig kümmern können.\n\nSie haben die Elitewache bekannt als die Kor'kron eingesetzt, um unseren Vormarsch auf der Insel der Eroberung aufzuhalten. Die Insel ist von äußerst wichtiger strategischer Bedeutung, {name}. Seht zu, dass unsere Jungs gewinnen!", sourceObjective = "Erringt den Sieg bei einer Partie auf dem Schlachtfeld \"Insel der Eroberung\" und kehrt zu einem Brigadegeneral der Allianz in irgendeiner Hauptstadt, Dalaran oder Shattrath zurück.", completion = "Die Horde wird es mit unseren Streitkräften nie aufnehmen können, so lange wir Leute wie Euch auf unserer Seite haben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14164] = { id = 14164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen: Insel der Eroberung", description = "Der Sieg in Nordend wird bald unser sein... doch nicht bevor wir in Eiskrone Fuß gefasst haben, um für den Transport und die Versorgung unserer Truppen zu sorgen.\n\nDie Insel der Eroberung ist ein idealer Ort. Sie ist einfach zu verteidigen und reich an Ressourcen. Die Allianz ist zu demselben Schluss gelangt und hat die 7. Legion ausgesandt, um unseren Streitkräften die Kontrolle zu entreißen.\n\nGeht, {name}, und sorgt dafür, dass die Horde um jeden Preis die Oberhand gewinnt!", sourceObjective = "Erringt den Sieg bei einer Partie auf dem Schlachtfeld \"Insel der Eroberung\" und kehrt zu einem Kriegshetzer der Horde in irgendeiner Hauptstadt, Dalaran oder Shattrath zurück.", completion = "Nichts wird sich zwischen uns und den endgültigen Sieg stellen. Für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[14165] = { id = 14165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalt wie Stein", description = "Die Arbeiter tun fast so, als bestünde Ihre Hauptaufgabe darin, sich zu beschweren. Wenn es nicht die harte Knochenarbeit, die Überstunden oder die geringe Bezahlung sind, ist es die Tatsache, dass sie von den Basilisken in Stein verwandelt werden. Irgendwas ist immer!\n\nAber ich glaube inzwischen, dass dieses ganze Arbeiter-in-Stein-Verwandeln ein echtes Geschäft für mich werden könnte. Was ist, wenn diese Leute jetzt hochwertiges Gestein sind? Meine jammernden Beschäftigten könnten für mich als Luxusbaumaterial mehr wert sein als als Arbeiter! Schnappt Euch einen versteinerten Bergfußminenarbeiter und schleppt ihn zu mir.", sourceObjective = "Holt einen versteinerten Bergfußminenarbeiter aus dem Tagebau am Gebirgsfuß und bringt ihn zurück zu Horzak Zignibble am Umschlagplatz der Raketenbahn von Orgrimmar.", completion = "Gutgut, nun sehen wir uns mal an, was wir hier haben...\n\n<Horzak untersucht die zerschmetterten Überreste des armen, versteinerten Minenarbeiters.>\n\nPah! Bröckelig! Unbrauchbar. Der gäbe nicht einmal eine gute Arbeitsplatte ab. Meine Bergarbeiter sind vielleicht mittelmäßige Arbeiter, aber sie geben lausige Steine ab.\n\n<Seufz.> Nun, ich nehme an, wir sollten diesen Arbeiter wieder verfleischlichen, sodass ich einen Teil meiner Investition zurückbekomme.", sourceObjectiveStatus = "unverified-source-field" }
quests[14166] = { id = 14166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Geist aus Dalaran auf dem Friedhof von Dalaran.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", progress = "Ihr habt keine Totenspeise, oder?", completion = "Oh, noch mehr köstliche Totenspeise, vielen Dank!\n\nHier, bitte, nehmt dies als Gegenleistung... eine kleine amüsante Aufmerksamkeit für die Feiertage.", sourceObjectiveStatus = "unverified-source-field" }
quests[14167] = { id = 14167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Zwergengeist auf dem Friedhof von Eisenschmiede.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14168] = { id = 14168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dankbaren Toten", description = "Es tut so gut, wieder bei Freunden und Familie zu sein, auch wenn ich es vielleicht etwas übertrieben habe... Ich habe schon alles gegessen, was sie für mich zubereitet haben!\n\nKann ich Euch um noch ein wenig mehr von dieser köstlichen Totenspeise bitten? Ich wäre Euch sehr dankbar...\n\nIch glaube, Chapman dort drüben verkauft das Rezept.", sourceObjective = "Besorgt Euch ein wenig Totenspeise und gebt sie dem heiteren Gnomengeist auf dem Friedhof von Eisenschmiede.\n\nBenutzt eine orangefarbene Ringelblume, um den ansonsten unsichtbaren Geist zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
